<?php
namespace App\Http\Controllers;
use App\Models\{Instansi,Pegawai,Pembinaan};
use Illuminate\Support\Carbon;
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
use Symfony\Component\HttpFoundation\StreamedResponse;
class ExportLaporanController extends Controller
{
 public function index(){ $this->authorize('viewAny',Pembinaan::class); $q=$this->query(); $years=(clone $q)->selectRaw('YEAR(tanggal_mulai) y')->distinct()->orderByDesc('y')->pluck('y'); $items=$this->filtered($q); $instansi=$items->pluck('instansi')->filter()->unique('id')->sortBy('nama')->values(); $pegawai=$items->flatMap(fn($item)=>$item->pegawai)->unique('id')->sortBy('nama_lengkap')->values(); $jenis=request('jenis','kegiatan'); $rows=$jenis==='narasumber'?$this->narasumberRows($items):$items; return view('export-laporan.index',['years'=>$years,'instansi'=>$instansi,'pegawai'=>$pegawai,'items'=>$items,'rows'=>$rows,'jenis'=>$jenis]); }
 public function excel(): StreamedResponse { $this->authorize('viewAny',Pembinaan::class); $items=$this->filtered($this->query()); $narasumber=request('jenis')==='narasumber'; $rows=$narasumber?$this->narasumberRows($items):$items; $book=new Spreadsheet(); $sheet=$book->getActiveSheet(); $headers=$narasumber?['Narasumber','Total Kegiatan','Sosialisasi','Integrasi','Kegiatan Terakhir']:['Instansi','Tanggal','Layanan','Metode','Narasumber','Status Dokumen']; foreach($headers as $i=>$h)$sheet->setCellValue(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($i+1)."1",$h); foreach($rows as $r=>$row){$values=$narasumber?[$row['nama'],$row['total'],$row['sosialisasi'],$row['integrasi'],$row['terakhir']]:[$row->instansi->nama,$row->tanggal_mulai->format('Y-m-d'),$row->layanan,$row->metode_pelaksanaan,$row->pegawai->pluck('nama_lengkap')->join(', '),$row->status_dokumen]; foreach($values as $c=>$v)$sheet->setCellValue(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($c+1).($r+2),$v);} $name=($narasumber?'Rekap_Kinerja_Narasumber_':'Laporan_Pembinaan_').now()->format('Ymd_His').'.xlsx'; return response()->streamDownload(function()use($book){(new Xlsx($book))->save('php://output');},$name,['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']); }
 public function template(){ $this->authorize('viewAny', Pembinaan::class); return response()->download(storage_path('app/templates/template-laporan-kegiatan-pembinaan.docx'), 'Template-Laporan-Kegiatan-Pembinaan.docx'); }
 private function query(){ $q=Pembinaan::with(['instansi','pegawai']); if(request()->user()->role==='pelaksana')$q->where('created_by',request()->user()->id); return $q; }
 private function narasumberRows($items){ return $items->flatMap(fn($item)=>$item->pegawai->map(fn($pegawai)=>['nama'=>$pegawai->nama_lengkap,'jenis'=>$item->jenis_pembinaan,'tanggal'=>$item->tanggal_mulai]))->groupBy('nama')->map(function($rows,$nama){ return ['nama'=>$nama,'total'=>$rows->count(),'sosialisasi'=>$rows->where('jenis','Sosialisasi Srikandi')->count(),'integrasi'=>$rows->where('jenis','Integrasi')->count(),'terakhir'=>$rows->max('tanggal')?->format('Y-m-d') ?? '-']; })->values(); }
 private function filtered($q){ if(request('tahun'))$q->whereYear('tanggal_mulai',request('tahun')); if(in_array(request('triwulan'),['1','2','3','4'],true)){ $s=((int)request('triwulan')-1)*3+1; $q->whereMonth('tanggal_mulai','>=',$s)->whereMonth('tanggal_mulai','<=',$s+2); } if(request('mulai'))$q->whereDate('tanggal_mulai','>=',request('mulai')); if(request('selesai'))$q->whereDate('tanggal_mulai','<=',request('selesai')); if(request('instansi_id'))$q->where('instansi_id',request('instansi_id')); if(request('layanan'))$q->where('layanan',request('layanan')); if(request('pegawai_id'))$q->whereHas('pegawai',fn($p)=>$p->whereKey(request('pegawai_id'))); return $q->latest('tanggal_mulai')->get(); }
}